// The full starters: text, seats and every field with its page and rectangle (generated by scripts/build-starters.mjs). Heavy (hundreds of KB): import it only from server code and build scripts, never from a page that ships to the browser.
import STARTER_DATA from "./starters.gen.json" with { type: "json" };
const TYPE_WORD = { signature: "signature", initials: "initials", date_signed: "date signed", text: "text", date: "date", number: "number", email: "email", phone: "phone", checkbox: "checkbox", dropdown: "choice", payment: "payment" };
export const FULL_TEMPLATES = STARTER_DATA.starters.map((s) => ({
  ...s, roles: s.seats.map((x) => x.role), fieldList: s.fields,
  fields: s.fields.map((f) => `${f.role}: ${f.label} (${TYPE_WORD[f.type] ?? f.type}${f.required ? "" : ", optional"})`),
  note: "A starting point in plain words, not legal advice. Change anything that does not fit before you send it.",
}));
